            if x.get('type') in('text','thinking'): cat['assistant '+x['type']]+=len(x.get('text','') or x.get('thinking',''))
            if x.get('type')=='tool_use': cat['assistant tool input']+=len(json.dumps(x['input']))
    if m.get('role')=='user':
        items=c if isinstance(c,list) else [{'type':'text','text':c or ''}]
        for x in items:
            if x.get('type')=='tool_result':
                t=x.get('content'); s=json.dumps(t) if not isinstance(t,str) else t
                k=tool_name.get(x.get('tool_use_id'),'?')
                if k.startswith('Read:'): k='Read '+k[5:]
