        s=json.dumps(d); cat['attachment/system']+=len(s)
tot=sum(cat.values())
for k,v in cat.most_common(25): print(f'{v/1000:8.1f}K chars  {k}  ({n.get(k,"")})')
print('total',tot/1000,'K chars')
EOF

